export const code = async (inputs) => {
  const str = (v) => String(v === undefined || v === null ? '' : v);
  const arr = (src) => Array.isArray(src) ? src : (src && Array.isArray(src.records) ? src.records : []);
  const flat = (rec) => {
    const out = {};
    const cells = (rec && rec.cells) || {};
    Object.keys(cells).forEach((fid) => {
      const c = cells[fid];
      if (c && typeof c === 'object' && typeof c.fieldName === 'string') out[c.fieldName] = c.value === undefined || c.value === null ? '' : String(c.value);
    });
    return out;
  };
  const texts = (inputs.texts && typeof inputs.texts === 'object') ? inputs.texts : {};
  const t = (k, vars) => {
    let s = String(texts[k] || k);
    if (vars) Object.keys(vars).forEach((key) => { s = s.split('{' + key + '}').join(String(vars[key])); });
    return s;
  };
  const ev = arr(inputs.eventRecords).map(flat).filter((e) => str(e.id) === str(inputs.eventId))[0];
  const authorChat = ev ? str(ev.staff_id) : '';
  const total = Number(inputs.total) || 0;
  const text = total === 0
    ? t('bcast.empty_segment')
    : t('bcast.finished', { sent: Number(inputs.sent) || 0, failed: Number(inputs.failed) || 0 });
  return { text: text, authorChat: authorChat !== '' ? authorChat : str(inputs.fallbackChat) };
};

export const code = async (inputs) => {
  const str = (v) => String(v === undefined || v === null ? '' : v);
  const arr = (src) => Array.isArray(src) ? src : (src && Array.isArray(src.records) ? src.records : []);
  const flat = (rec) => {
    const out = {};
    const cells = (rec && rec.cells) || {};
    Object.keys(cells).forEach((fid) => {
      const c = cells[fid];
      if (c && typeof c === 'object' && typeof c.fieldName === 'string') out[c.fieldName] = c.value === undefined || c.value === null ? '' : String(c.value);
    });
    return out;
  };
  const texts = (inputs.texts && typeof inputs.texts === 'object') ? inputs.texts : {};
  const t = (k, vars) => {
    let s = String(texts[k] || k);
    if (vars) Object.keys(vars).forEach((key) => { s = s.split('{' + key + '}').join(String(vars[key])); });
    return s;
  };
  const seg = str(inputs.segment);
  const blocked = {};
  arr(inputs.usersByIdsRecords).map(flat).forEach((u) => {
    if (str(u.blocked_bot) === 'true') blocked[str(u.telegram_id)] = true;
  });
  arr(inputs.consentRecords).map(flat).forEach((u) => {
    if (str(u.blocked_bot) === 'true') blocked[str(u.telegram_id)] = true;
  });
  let ids = [];
  if (seg === 'all_consent') {
    ids = arr(inputs.consentRecords).map(flat)
      .filter((u) => str(u.consent_marketing) === 'true' && str(u.telegram_id) !== '' && !blocked[str(u.telegram_id)])
      .map((u) => str(u.telegram_id));
  } else {
    const regs = arr(inputs.regRecords).map(flat)
      .filter((r) => str(r.event_id) === str(inputs.eventId) && str(r.status) === 'registered');
    const attended = {};
    regs.forEach((r) => { if (str(r.checked_in_at) !== '') attended[str(r.telegram_id)] = true; });
    if (seg === 'attended') ids = Object.keys(attended);
    else if (seg === 'no_show') ids = regs.filter((r) => str(r.checked_in_at) === '' && !attended[str(r.telegram_id)]).map((r) => str(r.telegram_id));
    else ids = regs.map((r) => str(r.telegram_id));
    ids = ids.filter((id) => id !== '' && !blocked[id]);
  }
  const seen = {};
  ids = ids.filter((id) => { if (seen[id]) return false; seen[id] = true; return true; });
  const members = ids.map((id) => ({ telegramId: id }));
  return {
    members: members, total: members.length, empty: members.length === 0,
    startedText: t('bcast.started', { count: members.length }),
    nowIso: new Date().toISOString(),
  };
};

