export const code = async (inputs) => {
  const str = (v) => String(v === undefined || v === null ? '' : v);
  const now = new Date().toISOString();
  const err = inputs.sendErr;
  const hasErr = err !== undefined && err !== null && !(typeof err === 'object' && Object.keys(err).length === 0) && err !== '';
  const txt = (v) => str(v).slice(0, 200);
  if (!hasErr) return { outcome: 'sent', errorText: '', now: now };
  let e = err;
  if (e && typeof e === 'object' && typeof e.message === 'string' && e.status === undefined) {
    try { e = JSON.parse(e.message); } catch (ex) { e = { message: e.message }; }
  }
  if (typeof e === 'string') { try { e = JSON.parse(e); } catch (ex) { e = { message: err }; } }
  const status = Number((e && e.status) || (e && e.responseBody && e.responseBody.error_code) || 0);
  const desc = str((e && e.responseBody && e.responseBody.description) || (e && e.apiMessage) || (e && e.message));
  if (status === 403 || /bot was blocked|blocked by the user|deactivated|kicked|forbidden/i.test(desc))
    return { outcome: 'blocked', errorText: txt(desc), now: now };
  return { outcome: 'failed', errorText: txt(desc || 'resend failed'), now: now };
};

export const code = async (inputs) => {
  const str = (v) => String(v === undefined || v === null ? '' : v);
  const now = new Date().toISOString();
  const err = inputs.sendErr;
  const hasErr = err !== undefined && err !== null && !(typeof err === 'object' && Object.keys(err).length === 0) && err !== '';
  const txt = (v) => str(v).slice(0, 200);
  if (!hasErr) {
    const out = inputs.sendOut;
    if (out && out.body && out.body.ok === false) return { outcome: 'failed', retryAfter: 0, errorText: txt(out.body.description), now: now };
    return { outcome: 'sent', retryAfter: 0, errorText: '', now: now };
  }
  let e = err;
  if (e && typeof e === 'object' && typeof e.message === 'string' && e.status === undefined) {
    try { e = JSON.parse(e.message); } catch (ex) { e = { message: e.message }; }
  }
  if (typeof e === 'string') { try { e = JSON.parse(e); } catch (ex) { e = { message: err }; } }
  const status = Number((e && e.status) || (e && e.responseBody && e.responseBody.error_code) || 0);
  const desc = str((e && e.responseBody && e.responseBody.description) || (e && e.apiMessage) || (e && e.message));
  if (status === 429 || /retry after/i.test(desc)) {
    const m = desc.match(/retry after (\d+)/i);
    let sec = m ? parseInt(m[1], 10) : 60;
    if (!isFinite(sec) || sec < 1) sec = 60;
    if (sec > 300) sec = 300;
    return { outcome: 'retry', retryAfter: sec, errorText: txt(desc), now: now };
  }
  if (status === 403 || /bot was blocked|blocked by the user|deactivated|kicked|forbidden/i.test(desc))
    return { outcome: 'blocked', retryAfter: 0, errorText: txt(desc), now: now };
  return { outcome: 'failed', retryAfter: 0, errorText: txt(desc || 'send failed'), now: now };
};

