export const code = async (inputs) => {
  const str = (v) => String(v === undefined || v === null ? '' : v);
  const arr = (src) => Array.isArray(src) ? src : (src && Array.isArray(src.records) ? src.records : []);
  const flat = (rec) => {
    const out = { __recordId: str(rec && rec.id) };
    const cells = (rec && rec.cells) || {};
    Object.keys(cells).forEach((fid) => {
      const c = cells[fid];
      if (c && typeof c === 'object' && typeof c.fieldName === 'string') out[c.fieldName] = c.value === undefined || c.value === null ? '' : String(c.value);
    });
    return out;
  };
  const parseDate = (s) => {
    s = str(s).trim();
    if (!s) return NaN;
    return Date.parse(/[Zz]$/.test(s) || /[+-][0-9]{2}:?[0-9]{2}$/.test(s) ? s : s + 'Z');
  };
  const fmtTash = (iso) => {
    const ms = parseDate(iso);
    if (!isFinite(ms)) return '';
    return new Intl.DateTimeFormat('ru-RU', { day: 'numeric', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit', timeZone: 'Asia/Tashkent' }).format(new Date(ms));
  };
  const texts = (inputs.texts && typeof inputs.texts === 'object') ? inputs.texts : {};
  const t = (k, vars) => {
    let s = String(texts[k] || k);
    if (vars) Object.keys(vars).forEach((key) => { s = s.split('{' + key + '}').join(String(vars[key])); });
    return s;
  };
  const stop = (notify) => ({
    action: 'stop', notify: notify, needNotify: notify !== '',
    bid: '', body: '', segment: '', eventId: '', recordId: '', sent: 0,
    mediaChatId: '', mediaMessageId: '',
  });
  const b = arr(inputs.broadcastRecords).map(flat)[0];
  if (!b || str(b.id) === '') return stop('');
  const phase = str(inputs.phase) || 'start';
  const status = str(b.status);
  const goSend = () => ({ action: 'send', notify: '', needNotify: false, bid: str(b.id), body: str(b.body), segment: str(b.segment), eventId: str(b.event_id), recordId: str(b.__recordId), sent: Number(b.sent) || 0, mediaChatId: str(b.media_chat_id), mediaMessageId: str(b.media_message_id) });
  if (status === 'done' || status === 'failed') return stop('');
  if (phase === 'send' && status === 'running') return goSend();
  if (phase === 'send' && status === 'draft') {
    // Самовызов send-фазы на несобранную рассылку — собираем сначала.
  } else if (phase !== 'start') {
    return stop('');
  } else if (status === 'running') {
    return goSend();
  }
  if (str(b.test_sent_at) === '') return stop(t('bcast.send.blocked_no_test'));
  const seg = str(b.segment);
  if (['all_consent', 'registered', 'attended', 'no_show'].indexOf(seg) < 0) return stop(t('common.err.generic'));
  const ev = arr(inputs.eventRecords).map(flat).filter((e) => str(e.id) === str(b.event_id))[0];
  if (!ev && seg !== 'all_consent') return stop(t('common.err.event_not_found'));
  if (seg === 'no_show' && ev) {
    const endsMs = parseDate(ev.ends_at);
    if (!isFinite(endsMs) || endsMs > Date.now()) {
      const when = fmtTash(ev.ends_at) || str(ev.ends_at);
      return stop(t('bcast.segment.no_show_locked', { when: when }));
    }
  }
  return { action: 'materialize', notify: '', needNotify: false, bid: str(b.id), body: str(b.body), segment: seg, eventId: str(b.event_id), recordId: str(b.__recordId), sent: 0, mediaChatId: str(b.media_chat_id), mediaMessageId: str(b.media_message_id) };
};

